
CREATE TYPE "FriendRequestStatus" AS ENUM ('PENDING','ACCEPTED','DECLINED');
CREATE TYPE "ApplicationStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "ModerationAction" AS ENUM ('WARN','KICK','BAN','UNBAN','TIMEOUT');
CREATE TABLE "ServerRole" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"name" TEXT NOT NULL,"color" TEXT,"position" INTEGER NOT NULL DEFAULT 0,"permissions" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ServerRole_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ServerRole_serverId_name_key" ON "ServerRole"("serverId","name");
CREATE INDEX "ServerRole_serverId_position_idx" ON "ServerRole"("serverId","position");
CREATE TABLE "ChannelCategory" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"name" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChannelCategory_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChannelCategory_serverId_position_idx" ON "ChannelCategory"("serverId","position");
ALTER TABLE "Channel" ADD COLUMN "categoryId" TEXT;
CREATE TABLE "ChannelPermissionOverride" ("id" TEXT NOT NULL,"channelId" TEXT NOT NULL,"roleId" TEXT,"memberId" TEXT,"allow" JSONB NOT NULL,"deny" JSONB NOT NULL,CONSTRAINT "ChannelPermissionOverride_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChannelPermissionOverride_channelId_idx" ON "ChannelPermissionOverride"("channelId");
ALTER TABLE "ServerMember" ADD COLUMN "roleId" TEXT;
CREATE TABLE "FriendRequest" ("id" TEXT NOT NULL,"senderId" TEXT NOT NULL,"receiverId" TEXT NOT NULL,"status" "FriendRequestStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FriendRequest_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FriendRequest_senderId_receiverId_key" ON "FriendRequest"("senderId","receiverId");
CREATE INDEX "FriendRequest_receiverId_status_idx" ON "FriendRequest"("receiverId","status");
CREATE TABLE "Conversation" ("id" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConversationMember" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"lastReadAt" TIMESTAMP(3),CONSTRAINT "ConversationMember_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ConversationMember_conversationId_userId_key" ON "ConversationMember"("conversationId","userId");
CREATE INDEX "ConversationMember_userId_idx" ON "ConversationMember"("userId");
CREATE TABLE "DirectMessage" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"editedAt" TIMESTAMP(3),CONSTRAINT "DirectMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "DirectMessage_conversationId_createdAt_idx" ON "DirectMessage"("conversationId","createdAt");
CREATE TABLE "Event" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"creatorId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"location" TEXT,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Event_serverId_startsAt_idx" ON "Event"("serverId","startsAt");
CREATE TABLE "ServerApplication" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"userId" TEXT NOT NULL,"answers" JSONB NOT NULL,"status" "ApplicationStatus" NOT NULL DEFAULT 'PENDING',"reviewedById" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ServerApplication_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ServerApplication_serverId_userId_key" ON "ServerApplication"("serverId","userId");
CREATE INDEX "ServerApplication_serverId_status_idx" ON "ServerApplication"("serverId","status");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"targetId" TEXT,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AuditLog_serverId_createdAt_idx" ON "AuditLog"("serverId","createdAt");
CREATE TABLE "ModerationRecord" ("id" TEXT NOT NULL,"serverId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"targetUserId" TEXT NOT NULL,"action" "ModerationAction" NOT NULL,"reason" TEXT,"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ModerationRecord_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ModerationRecord_serverId_createdAt_idx" ON "ModerationRecord"("serverId","createdAt");
CREATE INDEX "ModerationRecord_targetUserId_action_idx" ON "ModerationRecord"("targetUserId","action");
CREATE TABLE "Attachment" ("id" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"uploaderId" TEXT NOT NULL,"messageId" TEXT,"directMessageId" TEXT,"channelId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Attachment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Attachment_storageKey_key" ON "Attachment"("storageKey");
CREATE INDEX "Attachment_uploaderId_createdAt_idx" ON "Attachment"("uploaderId","createdAt");
CREATE TABLE "MessageReaction" ("id" TEXT NOT NULL,"messageId" TEXT NOT NULL,"channelId" TEXT NOT NULL,"userId" TEXT NOT NULL,"emoji" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MessageReaction_pkey" PRIMARY KEY ("id"));
